import {clamp} from './engine.js?v=20261009-auto-crossing';
import {structureSettings} from './structure-settings.js?v=20261009-auto-crossing';
export const KERB_MODES={inherit:'Use circuit setting',both:'Both sides',left:'Left side',right:'Right side',off:'No kerbs'};
export function turnBoardSettings(value={}){return {ten:value?.ten!==false,five:value?.five!==false,side:['left','right'].includes(value?.side)?value.side:'auto',entryOffset:clamp(Number(value?.entryOffset)||0,-10,10)};}
export function turnBoards(point={}){const settings={};for(const [key,value] of Object.entries(point.turnBoards||{}).slice(0,32))if(/^(left|right)_\d{1,2}$/.test(key))settings[key]=turnBoardSettings(value);return settings;}
export function reverseTurnBoards(point={},counts={}){const boards=turnBoards(point),result={};for(const direction of ['left','right']){const keys=Object.keys(boards).filter(key=>key.startsWith(direction+'_')).sort((a,b)=>Number(a.split('_')[1])-Number(b.split('_')[1]));const last=Math.max((counts[direction]||0)-1,...keys.map(key=>Number(key.split('_')[1])));for(const key of keys){const value=boards[key];result[`${direction==='left'?'right':'left'}_${last-Number(key.split('_')[1])}`]={...value,side:value.side==='left'?'right':value.side==='right'?'left':'auto'};}}return result;}
export function cornerSettings(point={}){return {rounding:clamp(Number.isFinite(point.rounding)?point.rounding:1,0,1),entryStrength:clamp(Number.isFinite(point.entryStrength)?point.entryStrength:1,0,1.6),exitStrength:clamp(Number.isFinite(point.exitStrength)?point.exitStrength:1,0,1.6),tangentRotation:clamp(Number(point.tangentRotation)||0,-60,60),cornerName:String(point.cornerName||'').slice(0,40),kerbs:KERB_MODES[point.kerbs]?point.kerbs:'inherit',kerbWidth:clamp(Number(point.kerbWidth)||.7,.25,2),turnBoards:turnBoards(point),structure:structureSettings(point.structure)};}
export function kerbSides(mode){return mode==='off'?[]:mode==='left'?[1]:mode==='right'?[-1]:[-1,1];}
